[
  {
    "question": "Which description correctly defines a database schema?",
    "options": {
      "A": "The actual data stored in the database at a particular moment",
      "B": "The structural definition of tables, columns, data types, and constraints",
      "C": "The result set returned by a SELECT query",
      "D": "The list of users and their privileges"
    },
    "correct_answer": "B",
    "explanation": "A schema is the blueprint of the database – it specifies tables, columns, data types, and constraints, whereas an instance is the actual data at a point in time.",
    "difficulty": "Medium"
  },
  {
    "question": "In a DBMS architecture, which component translates a SQL statement into an execution plan?",
    "options": {
      "A": "Transaction manager",
      "B": "Query processor",
      "C": "Storage manager",
      "D": "Authorization manager"
    },
    "correct_answer": "B",
    "explanation": "The query processor parses, validates, and optimizes SQL statements, producing an execution plan that the storage manager then carries out.",
    "difficulty": "Medium"
  },
  {
    "question": "Logical data independence allows:",
    "options": {
      "A": "Changes to physical storage structures without affecting the logical schema",
      "B": "Changes to the logical schema without requiring changes to application programs",
      "C": "Addition of new users without altering any data definitions",
      "D": "Encryption of data without modifying the schema"
    },
    "correct_answer": "B",
    "explanation": "Logical data independence means the logical view (tables, columns, relationships) can be altered without impacting external applications that rely on it.",
    "difficulty": "Medium"
  },
  {
    "question": "Within the syllabus, the term \"metadata\" refers to:",
    "options": {
      "A": "Data that describes the structure, constraints, and organization of the database",
      "B": "The actual user‑entered data stored in tables",
      "C": "Index files used to speed up query processing",
      "D": "Transaction log records for recovery"
    },
    "correct_answer": "A",
    "explanation": "Metadata is \"data about data\" and is stored in the catalog; it defines schemas, tables, columns, and other structural information.",
    "difficulty": "Medium"
  },
  {
    "question": "Which statement accurately describes the role of the recovery manager in a DBMS?",
    "options": {
      "A": "It guarantees atomicity and durability during transaction execution",
      "B": "It restores the database to a consistent state after a crash or failure",
      "C": "It creates optimal execution plans for queries",
      "D": "It enforces primary‑key and foreign‑key constraints"
    },
    "correct_answer": "B",
    "explanation": "The recovery manager uses logs and checkpoint information to bring the database back to a consistent state after a failure, handling roll‑back and roll‑forward operations.",
    "difficulty": "Medium"
  }
]
